async function readAround(path, patterns) {
  const content = await tools.read({path});
  const lines = content.split('\n');
  const hits = [];
  for (const p of patterns) {
    lines.forEach((l, i) => {
      if (l.includes(p)) hits.push(`${path}:${i+1}: ${l.trim()}`);
    });
  }
  return hits.join('\n');
}

